1	package warranty
2	
3	import (
4		"errors"
5		"sync"
6		"testing"
7		"time"
8	)
9	
10	// 本文件回归保障同一使用编号在并发提交下只产生一次真实扣减：首次成功把使用
11	// 编号与承诺编号、使用数量绑定（当前时刻不属于绑定内容）。此后相同内容的提交
12	// 都取回同一份完整使用记录，不同内容的提交一律 ErrConflict；无论成功返回多少
13	// 次，承诺累计已用数量与备件实物库存都只变化一次，有效占用只减少实际使用的
14	// 数量，可承诺数量保持原值。这些测试只沿用登记、预留、使用与查询的既有公开
15	// 行为。
16	
17	// concurrentUseCall 是一次并发使用提交的入参。
18	type concurrentUseCall struct {
19		usageID  string
20		commitID string
21		quantity int
22		now      time.Time
23	}
24	
25	// concurrentUseResult 是一次并发使用提交的结果。
26	type concurrentUseResult struct {
27		usage Usage
28		err   error
29	}
30	
31	// fanOutConcurrentUse 让全部调用在同一道闸机释放后同时进入 Use，尽量制造交叉；
32	// 返回与调用一一对应的结果，调用方按下标分组核对成功记录与冲突。
33	func fanOutConcurrentUse(s *Store, calls []concurrentUseCall) []concurrentUseResult {
34		results := make([]concurrentUseResult, len(calls))
35		var wg sync.WaitGroup
36		start := make(chan struct{})
37		for i, c := range calls {
38			wg.Add(1)
39			go func(i int, c concurrentUseCall) {
40				defer wg.Done()
41				<-start
42				results[i].usage, results[i].err = s.Use(c.usageID, c.commitID, c.quantity, c.now)
43			}(i, c)
44		}
45		close(start)
46		wg.Wait()
47		return results
48	}
49	
50	// identicalUseCalls 构造 n 个内容完全相同的使用调用；每个调用给不同但都处于
51	// 承诺有效期内的当前时刻，以证明当前时刻不属于绑定内容。
52	func identicalUseCalls(usageID, commitID string, quantity, n int) []concurrentUseCall {
53		calls := make([]concurrentUseCall, n)
54		for i := range calls {
55			calls[i] = concurrentUseCall{
56				usageID:  usageID,
57				commitID: commitID,
58				quantity: quantity,
59				now:      nowOK.Add(time.Duration(i) * time.Hour),
60			}
61		}
62		return calls
63	}
64	
65	// TestConcurrentUseSameIDDeductsOnce 验证多个调用同时提交相同的使用编号、承诺
66	// 编号和数量时全部成功、返回同一份完整使用记录，但承诺已用数量与实物库存只
67	// 变化一次。含“这一次恰好耗尽承诺余量”的边界：其余相同内容提交仍取回首次
68	// 结果，不能被当作新的超量使用拒绝。
69	func TestConcurrentUseSameIDDeductsOnce(t *testing.T) {
70		t.Run("partial use", func(t *testing.T) {
71			s := newStore(t)
72			if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
73				t.Fatalf("reserve: %v", err)
74			}
75			const n = 16
76			results := fanOutConcurrentUse(s, identicalUseCalls("u1", "c1", 2, n))
77	
78			want := Usage{ID: "u1", CommitmentID: "c1", Quantity: 2}
79			for i, r := range results {
80				if r.err != nil || r.usage != want {
81					t.Fatalf("call %d = %+v, err %v; want first record %+v", i, r.usage, r.err, want)
82				}
83			}
84			// 成功返回 n 次，真实扣减只有一次：实物八件、有效占用三件（c1 未用三）。
85			st, _ := s.PartStatus("part1", nowOK)
86			if st.PhysicalRemaining != 8 || st.ActiveOccupied != 3 || st.Committable != 5 {
87				t.Fatalf("stock = %+v, want phys=8 occupied=3 committable=5", st)
88			}
89			c1, _ := s.Commitment("c1")
90			if c1.Used != 2 || c1.Unused() != 3 {
91				t.Fatalf("c1 = used %d / unused %d, want 2/3", c1.Used, c1.Unused())
92			}
93		})
94	
95		t.Run("exactly exhausts remaining", func(t *testing.T) {
96			s := newStore(t)
97			if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
98				t.Fatalf("reserve: %v", err)
99			}
100			const n = 16
101			results := fanOutConcurrentUse(s, identicalUseCalls("u1", "c1", 5, n))
102	
103			want := Usage{ID: "u1", CommitmentID: "c1", Quantity: 5}
104			for i, r := range results {
105				// 恰好耗尽余量：相同内容的并发提交仍取回首次结果，不按超量使用拒绝。
106				if r.err != nil || r.usage != want {
107					t.Fatalf("call %d = %+v, err %v; want first record %+v", i, r.usage, r.err, want)
108				}
109			}
110			st, _ := s.PartStatus("part1", nowOK)
111			if st.PhysicalRemaining != 5 || st.ActiveOccupied != 0 || st.Committable != 5 {
112				t.Fatalf("stock = %+v, want phys=5 occupied=0 committable=5", st)
113			}
114			c1, _ := s.Commitment("c1")
115			if c1.Used != 5 || c1.Unused() != 0 {
116				t.Fatalf("c1 = used %d / unused %d, want 5/0", c1.Used, c1.Unused())
117			}
118			// 对照：耗尽之后新编号的新使用确实被当作超量使用拒绝；同编号原样提交
119			// （即使在更晚的当前时刻）仍只取回首次记录，不再次扣减。
120			if _, err := s.Use("uNew", "c1", 1, nowOK); !errors.Is(err, ErrUsageExceeded) {
121				t.Fatalf("fresh use after exhaustion: got %v, want ErrUsageExceeded", err)
122			}
123			if got, err := s.Use("u1", "c1", 5, nowOK.Add(day)); err != nil || got != want {
124				t.Fatalf("same content after exhaustion = %+v, err %v; want %+v", got, err, want)
125			}
126			if again, _ := s.PartStatus("part1", nowOK); again.PhysicalRemaining != 5 {
127				t.Fatalf("physical remaining = %d, want still 5", again.PhysicalRemaining)
128			}
129		})
130	}
131	
132	// TestConcurrentUseSameIDDifferentCommitmentSingleWinner 对应用户给出的主例：
133	// 两笔承诺各预留同一备件五件和三件，两组调用同时用同一个尚未成功占用的使用
134	// 编号分别使用两件。哪组先成功不作保证，但只能有一份内容成为成功记录：胜出
135	// 组全部成功并返回同一结果，落败组全部 ErrConflict。结束后实物剩余八件、有效
136	// 占用六件、可承诺两件；只有胜出承诺已用两件，落败承诺保持未使用。
137	func TestConcurrentUseSameIDDifferentCommitmentSingleWinner(t *testing.T) {
138		s := newStore(t)
139		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
140			t.Fatalf("reserve c1: %v", err)
141		}
142		if _, err := s.Reserve("c2", "r1", "part1", 3, expiryOK, nowOK); err != nil {
143			t.Fatalf("reserve c2: %v", err)
144		}
145	
146		const n = 12
147		calls := make([]concurrentUseCall, 0, 2*n)
148		for i := 0; i < n; i++ {
149			calls = append(calls, concurrentUseCall{"uX", "c1", 2, nowOK.Add(time.Duration(i) * time.Minute)})
150		}
151		for i := 0; i < n; i++ {
152			calls = append(calls, concurrentUseCall{"uX", "c2", 2, nowOK.Add(time.Duration(i) * time.Minute)})
153		}
154		results := fanOutConcurrentUse(s, calls)
155	
156		// 胜出者由实际数量判定（调用结果必须与实际扣减对应）：恰有一笔承诺已用两件。
157		c1c, _ := s.Commitment("c1")
158		c2c, _ := s.Commitment("c2")
159		var winner, loser string
160		switch {
161		case c1c.Used == 2 && c2c.Used == 0:
162			winner, loser = "c1", "c2"
163		case c1c.Used == 0 && c2c.Used == 2:
164			winner, loser = "c2", "c1"
165		default:
166			t.Fatalf("ambiguous deductions: c1 used=%d c2 used=%d, want exactly one at 2", c1c.Used, c2c.Used)
167		}
168		winningUsage := Usage{ID: "uX", CommitmentID: winner, Quantity: 2}
169	
170		// 与胜出内容相同的调用全部成功且返回同一记录，另一组全部 ErrConflict。
171		success, conflict := 0, 0
172		for i, c := range calls {
173			r := results[i]
174			if c.commitID == winner {
175				if r.err != nil || r.usage != winningUsage {
176					t.Fatalf("winner-group call %d = %+v, err %v; want %+v", i, r.usage, r.err, winningUsage)
177				}
178				success++
179			} else {
180				if !errors.Is(r.err, ErrConflict) || r.usage != (Usage{}) {
181					t.Fatalf("loser-group call %d = %+v, err %v; want ErrConflict with empty result", i, r.usage, r.err)
182				}
183				conflict++
184			}
185		}
186		if success != n || conflict != n {
187			t.Fatalf("success=%d conflict=%d, want exactly %d/%d", success, conflict, n, n)
188		}
189	
190		// 结束数量：实物八件、有效占用六件（c1 与 c2 未用之和）、可承诺两件。
191		st, _ := s.PartStatus("part1", nowOK)
192		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 6 || st.Committable != 2 {
193			t.Fatalf("stock = %+v, want phys=8 occupied=6 committable=2 (winner=%s)", st, winner)
194		}
195	
196		// 赛后按胜出内容提交取回原记录；按落败内容提交仍冲突，均不再次扣减。
197		if got, err := s.Use("uX", winner, 2, nowOK.Add(2*day)); err != nil || got != winningUsage {
198			t.Fatalf("winner content retry = %+v, err %v; want %+v", got, err, winningUsage)
199		}
200		if _, err := s.Use("uX", loser, 2, nowOK.Add(2*day)); !errors.Is(err, ErrConflict) {
201			t.Fatalf("loser content retry: got %v, want ErrConflict", err)
202		}
203		st2, _ := s.PartStatus("part1", nowOK)
204		if st2.PhysicalRemaining != 8 || st2.ActiveOccupied != 6 {
205			t.Fatalf("post-hoc retries changed quantities: %+v", st2)
206		}
207	
208		// 落败承诺保持未使用：换新编号仍可正常使用；可承诺两件也真实可再预留。
209		if u, err := s.Use("uY", loser, 1, nowOK); err != nil {
210			t.Fatalf("loser commitment %s should remain usable: %v", loser, err)
211		} else if u.CommitmentID != loser || u.Quantity != 1 {
212			t.Fatalf("use on loser = %+v, want commitment %s qty 1", u, loser)
213		}
214		if _, err := s.Reserve("c3", "r1", "part1", 2, expiryOK, nowOK); err != nil {
215			t.Fatalf("reserve remaining committable 2: %v", err)
216		}
217	}
218	
219	// TestConcurrentUseSameIDDifferentQuantitySingleWinner 验证同一承诺下仅使用
220	// 数量不同也属于不同内容竞争同一编号：成功记录与最终扣减量必须对应同一份
221	// 提交（两件或四件），胜出组全部返回同一记录，落败组全部 ErrConflict。赛后
222	// 按胜出内容提交取回原记录，按另一份内容提交仍冲突，冲突不覆盖记录、不额外
223	// 扣减。
224	func TestConcurrentUseSameIDDifferentQuantitySingleWinner(t *testing.T) {
225		s := newStore(t)
226		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
227			t.Fatalf("reserve: %v", err)
228		}
229	
230		const n = 12
231		calls := make([]concurrentUseCall, 0, 2*n)
232		for i := 0; i < n; i++ {
233			calls = append(calls, concurrentUseCall{"uQ", "c1", 2, nowOK.Add(time.Duration(i) * time.Minute)})
234		}
235		for i := 0; i < n; i++ {
236			calls = append(calls, concurrentUseCall{"uQ", "c1", 4, nowOK.Add(time.Duration(i) * time.Minute)})
237		}
238		results := fanOutConcurrentUse(s, calls)
239	
240		// 胜出数量由承诺实际已用数量判定：只能是两份内容之一，不能是两者叠加。
241		c1c, _ := s.Commitment("c1")
242		var winnerQty, loserQty int
243		switch c1c.Used {
244		case 2:
245			winnerQty, loserQty = 2, 4
246		case 4:
247			winnerQty, loserQty = 4, 2
248		default:
249			t.Fatalf("c1 used = %d, want exactly 2 or 4 (single winning content)", c1c.Used)
250		}
251		winningUsage := Usage{ID: "uQ", CommitmentID: "c1", Quantity: winnerQty}
252	
253		success, conflict := 0, 0
254		for i, c := range calls {
255			r := results[i]
256			if c.quantity == winnerQty {
257				if r.err != nil || r.usage != winningUsage {
258					t.Fatalf("winner-group call %d = %+v, err %v; want %+v", i, r.usage, r.err, winningUsage)
259				}
260				success++
261			} else {
262				// 落败组即使其数量此刻会超过被首次使用后压缩的余量，也只能得到
263				// 编号冲突，不能报超量使用，更不能扣减。
264				if !errors.Is(r.err, ErrConflict) || r.usage != (Usage{}) {
265					t.Fatalf("loser-group call %d = %+v, err %v; want ErrConflict with empty result", i, r.usage, r.err)
266				}
267				conflict++
268			}
269		}
270		if success != n || conflict != n {
271			t.Fatalf("success=%d conflict=%d, want exactly %d/%d", success, conflict, n, n)
272		}
273	
274		// 实物与有效占用只随胜出数量变化一次；可承诺数量恒为初始的五件。
275		st, _ := s.PartStatus("part1", nowOK)
276		wantPhys, wantOccupied := 10-winnerQty, 5-winnerQty
277		if st.PhysicalRemaining != wantPhys || st.ActiveOccupied != wantOccupied || st.Committable != 5 {
278			t.Fatalf("winner qty %d: stock = %+v, want phys=%d occupied=%d committable=5",
279				winnerQty, st, wantPhys, wantOccupied)
280		}
281	
282		// 赛后按胜出内容提交取回原记录；按落败内容提交仍冲突，数量不再变化。
283		if got, err := s.Use("uQ", "c1", winnerQty, nowOK.Add(day)); err != nil || got != winningUsage {
284			t.Fatalf("winner content retry = %+v, err %v; want %+v", got, err, winningUsage)
285		}
286		if _, err := s.Use("uQ", "c1", loserQty, nowOK.Add(day)); !errors.Is(err, ErrConflict) {
287			t.Fatalf("loser content retry: got %v, want ErrConflict", err)
288		}
289		c1b, _ := s.Commitment("c1")
290		if c1b.Used != winnerQty {
291			t.Fatalf("c1 used after retries = %d, want still %d", c1b.Used, winnerQty)
292		}
293	}
