package warranty

import (
	"errors"
	"sync"
	"testing"
	"time"
)

// 本文件回归保障同一使用编号在并发提交下只产生一次真实扣减：首次成功把使用
// 编号与承诺编号、使用数量绑定（当前时刻不属于绑定内容）。此后相同内容的提交
// 都取回同一份完整使用记录，不同内容的提交一律 ErrConflict；无论成功返回多少
// 次，承诺累计已用数量与备件实物库存都只变化一次，有效占用只减少实际使用的
// 数量，可承诺数量保持原值。这些测试只沿用登记、预留、使用与查询的既有公开
// 行为。

// concurrentUseCall 是一次并发使用提交的入参。
type concurrentUseCall struct {
	usageID  string
	commitID string
	quantity int
	now      time.Time
}

// concurrentUseResult 是一次并发使用提交的结果。
type concurrentUseResult struct {
	usage Usage
	err   error
}

// fanOutConcurrentUse 让全部调用在同一道闸机释放后同时进入 Use，尽量制造交叉；
// 返回与调用一一对应的结果，调用方按下标分组核对成功记录与冲突。
func fanOutConcurrentUse(s *Store, calls []concurrentUseCall) []concurrentUseResult {
	results := make([]concurrentUseResult, len(calls))
	var wg sync.WaitGroup
	start := make(chan struct{})
	for i, c := range calls {
		wg.Add(1)
		go func(i int, c concurrentUseCall) {
			defer wg.Done()
			<-start
			results[i].usage, results[i].err = s.Use(c.usageID, c.commitID, c.quantity, c.now)
		}(i, c)
	}
	close(start)
	wg.Wait()
	return results
}

// identicalUseCalls 构造 n 个内容完全相同的使用调用；每个调用给不同但都处于
// 承诺有效期内的当前时刻，以证明当前时刻不属于绑定内容。
func identicalUseCalls(usageID, commitID string, quantity, n int) []concurrentUseCall {
	calls := make([]concurrentUseCall, n)
	for i := range calls {
		calls[i] = concurrentUseCall{
			usageID:  usageID,
			commitID: commitID,
			quantity: quantity,
			now:      nowOK.Add(time.Duration(i) * time.Hour),
		}
	}
	return calls
}

// TestConcurrentUseSameIDDeductsOnce 验证多个调用同时提交相同的使用编号、承诺
// 编号和数量时全部成功、返回同一份完整使用记录，但承诺已用数量与实物库存只
// 变化一次。含“这一次恰好耗尽承诺余量”的边界：其余相同内容提交仍取回首次
// 结果，不能被当作新的超量使用拒绝。
func TestConcurrentUseSameIDDeductsOnce(t *testing.T) {
	t.Run("partial use", func(t *testing.T) {
		s := newStore(t)
		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
			t.Fatalf("reserve: %v", err)
		}
		const n = 16
		results := fanOutConcurrentUse(s, identicalUseCalls("u1", "c1", 2, n))

		want := Usage{ID: "u1", CommitmentID: "c1", Quantity: 2}
		for i, r := range results {
			if r.err != nil || r.usage != want {
				t.Fatalf("call %d = %+v, err %v; want first record %+v", i, r.usage, r.err, want)
			}
		}
		// 成功返回 n 次，真实扣减只有一次：实物八件、有效占用三件（c1 未用三）。
		st, _ := s.PartStatus("part1", nowOK)
		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 3 || st.Committable != 5 {
			t.Fatalf("stock = %+v, want phys=8 occupied=3 committable=5", st)
		}
		c1, _ := s.Commitment("c1")
		if c1.Used != 2 || c1.Unused() != 3 {
			t.Fatalf("c1 = used %d / unused %d, want 2/3", c1.Used, c1.Unused())
		}
	})

	t.Run("exactly exhausts remaining", func(t *testing.T) {
		s := newStore(t)
		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
			t.Fatalf("reserve: %v", err)
		}
		const n = 16
		results := fanOutConcurrentUse(s, identicalUseCalls("u1", "c1", 5, n))

		want := Usage{ID: "u1", CommitmentID: "c1", Quantity: 5}
		for i, r := range results {
			// 恰好耗尽余量：相同内容的并发提交仍取回首次结果，不按超量使用拒绝。
			if r.err != nil || r.usage != want {
				t.Fatalf("call %d = %+v, err %v; want first record %+v", i, r.usage, r.err, want)
			}
		}
		st, _ := s.PartStatus("part1", nowOK)
		if st.PhysicalRemaining != 5 || st.ActiveOccupied != 0 || st.Committable != 5 {
			t.Fatalf("stock = %+v, want phys=5 occupied=0 committable=5", st)
		}
		c1, _ := s.Commitment("c1")
		if c1.Used != 5 || c1.Unused() != 0 {
			t.Fatalf("c1 = used %d / unused %d, want 5/0", c1.Used, c1.Unused())
		}
		// 对照：耗尽之后新编号的新使用确实被当作超量使用拒绝；同编号原样提交
		// （即使在更晚的当前时刻）仍只取回首次记录，不再次扣减。
		if _, err := s.Use("uNew", "c1", 1, nowOK); !errors.Is(err, ErrUsageExceeded) {
			t.Fatalf("fresh use after exhaustion: got %v, want ErrUsageExceeded", err)
		}
		if got, err := s.Use("u1", "c1", 5, nowOK.Add(day)); err != nil || got != want {
			t.Fatalf("same content after exhaustion = %+v, err %v; want %+v", got, err, want)
		}
		if again, _ := s.PartStatus("part1", nowOK); again.PhysicalRemaining != 5 {
			t.Fatalf("physical remaining = %d, want still 5", again.PhysicalRemaining)
		}
	})
}

// TestConcurrentUseSameIDDifferentCommitmentSingleWinner 对应用户给出的主例：
// 两笔承诺各预留同一备件五件和三件，两组调用同时用同一个尚未成功占用的使用
// 编号分别使用两件。哪组先成功不作保证，但只能有一份内容成为成功记录：胜出
// 组全部成功并返回同一结果，落败组全部 ErrConflict。结束后实物剩余八件、有效
// 占用六件、可承诺两件；只有胜出承诺已用两件，落败承诺保持未使用。
func TestConcurrentUseSameIDDifferentCommitmentSingleWinner(t *testing.T) {
	s := newStore(t)
	if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
		t.Fatalf("reserve c1: %v", err)
	}
	if _, err := s.Reserve("c2", "r1", "part1", 3, expiryOK, nowOK); err != nil {
		t.Fatalf("reserve c2: %v", err)
	}

	const n = 12
	calls := make([]concurrentUseCall, 0, 2*n)
	for i := 0; i < n; i++ {
		calls = append(calls, concurrentUseCall{"uX", "c1", 2, nowOK.Add(time.Duration(i) * time.Minute)})
	}
	for i := 0; i < n; i++ {
		calls = append(calls, concurrentUseCall{"uX", "c2", 2, nowOK.Add(time.Duration(i) * time.Minute)})
	}
	results := fanOutConcurrentUse(s, calls)

	// 胜出者由实际数量判定（调用结果必须与实际扣减对应）：恰有一笔承诺已用两件。
	c1c, _ := s.Commitment("c1")
	c2c, _ := s.Commitment("c2")
	var winner, loser string
	switch {
	case c1c.Used == 2 && c2c.Used == 0:
		winner, loser = "c1", "c2"
	case c1c.Used == 0 && c2c.Used == 2:
		winner, loser = "c2", "c1"
	default:
		t.Fatalf("ambiguous deductions: c1 used=%d c2 used=%d, want exactly one at 2", c1c.Used, c2c.Used)
	}
	winningUsage := Usage{ID: "uX", CommitmentID: winner, Quantity: 2}

	// 与胜出内容相同的调用全部成功且返回同一记录，另一组全部 ErrConflict。
	success, conflict := 0, 0
	for i, c := range calls {
		r := results[i]
		if c.commitID == winner {
			if r.err != nil || r.usage != winningUsage {
				t.Fatalf("winner-group call %d = %+v, err %v; want %+v", i, r.usage, r.err, winningUsage)
			}
			success++
		} else {
			if !errors.Is(r.err, ErrConflict) || r.usage != (Usage{}) {
				t.Fatalf("loser-group call %d = %+v, err %v; want ErrConflict with empty result", i, r.usage, r.err)
			}
			conflict++
		}
	}
	if success != n || conflict != n {
		t.Fatalf("success=%d conflict=%d, want exactly %d/%d", success, conflict, n, n)
	}

	// 结束数量：实物八件、有效占用六件（c1 与 c2 未用之和）、可承诺两件。
	st, _ := s.PartStatus("part1", nowOK)
	if st.PhysicalRemaining != 8 || st.ActiveOccupied != 6 || st.Committable != 2 {
		t.Fatalf("stock = %+v, want phys=8 occupied=6 committable=2 (winner=%s)", st, winner)
	}

	// 赛后按胜出内容提交取回原记录；按落败内容提交仍冲突，均不再次扣减。
	if got, err := s.Use("uX", winner, 2, nowOK.Add(2*day)); err != nil || got != winningUsage {
		t.Fatalf("winner content retry = %+v, err %v; want %+v", got, err, winningUsage)
	}
	if _, err := s.Use("uX", loser, 2, nowOK.Add(2*day)); !errors.Is(err, ErrConflict) {
		t.Fatalf("loser content retry: got %v, want ErrConflict", err)
	}
	st2, _ := s.PartStatus("part1", nowOK)
	if st2.PhysicalRemaining != 8 || st2.ActiveOccupied != 6 {
		t.Fatalf("post-hoc retries changed quantities: %+v", st2)
	}

	// 落败承诺保持未使用：换新编号仍可正常使用；可承诺两件也真实可再预留。
	if u, err := s.Use("uY", loser, 1, nowOK); err != nil {
		t.Fatalf("loser commitment %s should remain usable: %v", loser, err)
	} else if u.CommitmentID != loser || u.Quantity != 1 {
		t.Fatalf("use on loser = %+v, want commitment %s qty 1", u, loser)
	}
	if _, err := s.Reserve("c3", "r1", "part1", 2, expiryOK, nowOK); err != nil {
		t.Fatalf("reserve remaining committable 2: %v", err)
	}
}

// TestConcurrentUseSameIDDifferentQuantitySingleWinner 验证同一承诺下仅使用
// 数量不同也属于不同内容竞争同一编号：成功记录与最终扣减量必须对应同一份
// 提交（两件或四件），胜出组全部返回同一记录，落败组全部 ErrConflict。赛后
// 按胜出内容提交取回原记录，按另一份内容提交仍冲突，冲突不覆盖记录、不额外
// 扣减。
func TestConcurrentUseSameIDDifferentQuantitySingleWinner(t *testing.T) {
	s := newStore(t)
	if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
		t.Fatalf("reserve: %v", err)
	}

	const n = 12
	calls := make([]concurrentUseCall, 0, 2*n)
	for i := 0; i < n; i++ {
		calls = append(calls, concurrentUseCall{"uQ", "c1", 2, nowOK.Add(time.Duration(i) * time.Minute)})
	}
	for i := 0; i < n; i++ {
		calls = append(calls, concurrentUseCall{"uQ", "c1", 4, nowOK.Add(time.Duration(i) * time.Minute)})
	}
	results := fanOutConcurrentUse(s, calls)

	// 胜出数量由承诺实际已用数量判定：只能是两份内容之一，不能是两者叠加。
	c1c, _ := s.Commitment("c1")
	var winnerQty, loserQty int
	switch c1c.Used {
	case 2:
		winnerQty, loserQty = 2, 4
	case 4:
		winnerQty, loserQty = 4, 2
	default:
		t.Fatalf("c1 used = %d, want exactly 2 or 4 (single winning content)", c1c.Used)
	}
	winningUsage := Usage{ID: "uQ", CommitmentID: "c1", Quantity: winnerQty}

	success, conflict := 0, 0
	for i, c := range calls {
		r := results[i]
		if c.quantity == winnerQty {
			if r.err != nil || r.usage != winningUsage {
				t.Fatalf("winner-group call %d = %+v, err %v; want %+v", i, r.usage, r.err, winningUsage)
			}
			success++
		} else {
			// 落败组即使其数量此刻会超过被首次使用后压缩的余量，也只能得到
			// 编号冲突，不能报超量使用，更不能扣减。
			if !errors.Is(r.err, ErrConflict) || r.usage != (Usage{}) {
				t.Fatalf("loser-group call %d = %+v, err %v; want ErrConflict with empty result", i, r.usage, r.err)
			}
			conflict++
		}
	}
	if success != n || conflict != n {
		t.Fatalf("success=%d conflict=%d, want exactly %d/%d", success, conflict, n, n)
	}

	// 实物与有效占用只随胜出数量变化一次；可承诺数量恒为初始的五件。
	st, _ := s.PartStatus("part1", nowOK)
	wantPhys, wantOccupied := 10-winnerQty, 5-winnerQty
	if st.PhysicalRemaining != wantPhys || st.ActiveOccupied != wantOccupied || st.Committable != 5 {
		t.Fatalf("winner qty %d: stock = %+v, want phys=%d occupied=%d committable=5",
			winnerQty, st, wantPhys, wantOccupied)
	}

	// 赛后按胜出内容提交取回原记录；按落败内容提交仍冲突，数量不再变化。
	if got, err := s.Use("uQ", "c1", winnerQty, nowOK.Add(day)); err != nil || got != winningUsage {
		t.Fatalf("winner content retry = %+v, err %v; want %+v", got, err, winningUsage)
	}
	if _, err := s.Use("uQ", "c1", loserQty, nowOK.Add(day)); !errors.Is(err, ErrConflict) {
		t.Fatalf("loser content retry: got %v, want ErrConflict", err)
	}
	c1b, _ := s.Commitment("c1")
	if c1b.Used != winnerQty {
		t.Fatalf("c1 used after retries = %d, want still %d", c1b.Used, winnerQty)
	}
}

package warranty

import (
	"fmt"
	"time"
)

// stockAccountLocked 按统一的库存规则核算指定备件当前的账目：实物剩余只扣除
// 成功使用的数量（即备件当前库存），有效占用是该备件所有未取消、未确认到期
// 承诺的未用总量，可承诺数量等于实物剩余减去有效占用。已取消或已确认到期的
// 承诺不计入占用；到期一经确认不可逆，与本次传入的当前时刻无关，因此这里
// 不接收当前时刻，时刻相关的到期确认由调用方在核算前对本次涉及的承诺显式
// 完成。新预留的库存核算与按备件的库存查询共用这一份账目，同一条库存规则
// 不再分别维护。
//
// 调用方须已确认备件存在。
func (s *Store) stockAccountLocked(partID string) StockBasis {
	account := StockBasis{PhysicalRemaining: s.parts[partID].Stock}
	for _, c := range s.commitments {
		if c.PartID != partID {
			continue
		}
		if c.Canceled || c.Expired {
			continue
		}
		account.ActiveOccupied += c.Unused()
	}
	account.Committable = account.PhysicalRemaining - account.ActiveOccupied
	return account
}

// Reserve 为请求预留一种备件，数量为正整数，到期时刻必须晚于本次提交的当前时刻。
// 每次首次预留都按当次时刻重新判断资格；可承诺数量等于剩余实物库存扣除所有
// 有效承诺的未用数量。库存不足、未知请求或备件、不合格请求都不占用数量。
//
// 新预留的库存核算会先按本次当前时刻确认该备件下已到期的承诺：当前时刻达到
// 其到期时刻的未取消承诺被永久标记到期，只释放未用占用、不增加实物库存；该
// 结果不可逆，之后即使传入更早时刻核算也不再计算其未用数量，不能再次占用已
// 释放给其他请求的数量。空编号、非正数量等参数非法，或请求、备件（含资格所
// 需产品）不存在而提前失败的调用，不用本次时刻确认任何承诺。
//
// 提交编号全局唯一。已成功的编号：
//   - 原样重试（请求编号、备件编号、数量和到期时刻一致；当前时刻不属于提交内容，
//     到期时刻按实际时刻比较，换时区表示仍算一致）只取回首次预留成功的完整承诺，
//     其中已用数量仍为零、取消标记仍为否，不重新判断资格与库存，不重复占用，不
//     追加历史，也不恢复已释放占用或补回已扣减的实物库存；无论请求后来过保、库存
//     不足，还是承诺已分批使用、全部使用、取消或到期，即使本次当前时刻等于或晚于
//     原到期时刻，均如此。
//   - 改请求、备件、数量或到期时刻任一项即返回 ErrConflict，即使新参数本身非法
//     （空请求、未知备件、零数量、已过去的到期时刻）也按编号冲突处理；失败记录挂在
//     本次提交指定的已知请求下，请求为空或不存在时不创建请求和历史。
//
// 首次成功与编号绑定在同一临界区内原子完成：同一个尚未成功预留的编号被两组不同
// 内容（请求、备件、数量或到期时刻不同）并发抢占，且每组内容都可能同时提交多次
// 时，只能有一份内容成为首次承诺——与其完全相同的并发提交全部成功并返回同一份
// 完整首次承诺（已用数量为零、未取消），另一组全部返回 ErrConflict，不能两笔都
// 成功，也不会把后来的内容写进已经成功的承诺；即使库存充足到能同时容纳两笔数量，
// 有效占用也只对应获胜数量（预留不扣减实物库存），承诺只归获胜请求。库存恰好被
// 首次成功预留用完时，同内容的其余并发提交仍取回首次结果而不是 ErrInsufficientStock，
// 另一组仍报编号冲突；赛后按胜出内容重试取回首次承诺，按落败内容重试仍冲突，库存
// 与归属保持原结果。获胜请求只留一条首次成功记录（保存当次资格与新增占用前的库存
// 依据），相同内容的其余成功返回不追加；落败请求的每次提交各留一条冲突失败记录，
// 保留当次数量、到期时刻与当前时刻，资格与库存依据均为空，记录不挂到获胜请求下。
//
// 尚未成功占用的编号继续按本次参数、资格和库存判断；失败记录照常保留，失败后允许
// 用该编号再次提交。每次首次预留成功及每次失败提交都会在对应请求下留下记录。
func (s *Store) Reserve(commitID, requestID, partID string, quantity int, expiry, now time.Time) (Commitment, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// 本次提交的历史记录骨架：承诺编号、备件、数量、到期时刻与当前时刻在各分支
	// 一致，统一在这里填写，各分支不再重复。record 按统一规则留痕：成功标记与
	// 失败类别互斥，资格与库存依据快照原样保存（提前失败时为 nil，不用合格资格
	// 或零库存替代缺失）；请求为空或尚未登记时不创建请求和历史。
	base := HistoryRecord{
		CommitID: commitID,
		PartID:   partID,
		Quantity: quantity,
		Expiry:   expiry,
		Now:      now,
	}
	record := func(success bool, herr HistoryError, elig *Eligibility, basis *StockBasis) {
		rec := base
		rec.Success = success
		rec.Error = herr
		rec.Eligibility = cloneEligibility(elig)
		rec.StockBasis = basis
		s.recordReserveLocked(requestID, rec)
	}

	// 已成功的编号优先按重复提交处理，优先于本次参数校验：原样重试不因本次当前
	// 时刻晚于到期时刻等参数问题失败；改内容则一律冲突。
	if first, ok := s.firstResults[commitID]; ok {
		if first.RequestID != requestID || first.PartID != partID ||
			first.Quantity != quantity || !first.Expiry.Equal(expiry) {
			// 冲突：在本次提交指定的已知请求下记录失败，不挂到原承诺所属请求。
			record(false, HistoryErrorConflict, nil, nil)
			return Commitment{}, fmt.Errorf("%w: commit id %q reused with different content", ErrConflict, commitID)
		}
		// 原样重试：返回首次成功时的承诺快照，不反映后来的使用、取消或到期。
		return first, nil
	}

	if commitID == "" || requestID == "" || partID == "" {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: commit/request/part id must not be empty", ErrInvalidParam)
	}
	if quantity <= 0 {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: reserve quantity must be a positive integer", ErrInvalidParam)
	}
	if !expiry.After(now) {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: expiry must be after current time", ErrInvalidParam)
	}

	req, ok := s.requests[requestID]
	if !ok {
		return Commitment{}, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	if _, ok := s.parts[partID]; !ok {
		record(false, HistoryErrorPartNotFound, nil, nil)
		return Commitment{}, fmt.Errorf("%w: part %q", ErrNotFound, partID)
	}
	elig, err := s.evaluateLocked(req, now)
	if err != nil {
		// 产品未登记：资格依据明确为空，不用合格替代缺失。
		record(false, HistoryErrorProductNotFound, nil, nil)
		return Commitment{}, err
	}

	// 库存核算前先按本次时刻确认该备件已到期的承诺。到期确认不可逆，之后
	// 即使传入更早时刻也不再计入占用。放在参数与引用校验之后：提前失败的
	// 非法或缺失引用调用不确认任何承诺。
	s.confirmPartExpiriesLocked(partID, now)

	// 库存依据：本次提交处理前的实物剩余、有效占用与可承诺数量，与库存
	// 查询共用同一份核算；在新增承诺落库之前取快照，本次新增占用不计入。
	stockBasis := s.stockAccountLocked(partID)

	if !elig.Eligible {
		record(false, HistoryErrorIneligible, elig, &stockBasis)
		return Commitment{}, fmt.Errorf("%w: %v", ErrIneligible, elig.Reasons)
	}

	if quantity > stockBasis.Committable {
		record(false, HistoryErrorInsufficientStock, elig, &stockBasis)
		return Commitment{}, fmt.Errorf("%w: need %d, committable %d", ErrInsufficientStock, quantity, stockBasis.Committable)
	}

	c := &Commitment{
		ID:        commitID,
		RequestID: requestID,
		PartID:    partID,
		Quantity:  quantity,
		Expiry:    expiry,
	}
	// 成功记录、承诺与首次结果快照在同一把锁内同时落库，查询不会看到只占用库存
	// 却没有成功记录的中间状态；快照独立于活动承诺，之后的使用、取消或到期不
	// 会改变原样重试取回的值。
	s.commitments[commitID] = c
	s.firstResults[commitID] = *c
	record(true, "", elig, &stockBasis)
	return *c, nil
}

// Use 使用一笔承诺，数量为正整数，分批扣减该承诺未用数量和剩余实物库存。
// 数量超过未用数量时整次失败，不改变任何记录。
//
// 使用编号全局唯一：相同编号且相同内容的重试返回首次成功结果，不再次扣减，
// 也不借本次时刻确认任何承诺到期；编号一旦已有成功记录，后续提交的承诺编号或
// 数量与首次成功内容不同即返回 ErrConflict——即使新内容本身非法（空承诺编号、
// 指向不存在的承诺、数量为零或负数、超过承诺余量），或新指定的承诺已取消或
// 到期，也一律按编号冲突处理：不扣减实物库存、不改变任何承诺的已用数量、不
// 释放占用，也不借本次时刻确认原承诺或新承诺到期，更不会用新内容覆盖原记录。
// 首次成功与编号绑定在同一临界区内原子完成：多个相同内容的并发提交全部成功并
// 返回同一份完整使用记录，但承诺累计已用数量与实物库存只随首次成功变化一次
// （恰好耗尽余量时其余提交仍取回首次结果，不会被当作新的超量使用）；首次成功
// 前两组不同内容并发抢占同一编号时，只有一份内容成为成功记录，与其相同的提交
// 全部取回该结果，另一组全部 ErrConflict，扣减量只对应胜出内容，落败承诺不变。
// 已经成功的使用在承诺取消或到期后原样重试，仍返回原结果，已确认到期的承诺
// 也不会因此重新开放。新使用（非重试）会按本次当前时刻确认这一笔承诺：已取消
// 或已确认到期，或本次时刻达到其到期时刻的，一律返回 ErrCommitmentClosed；到期
// 一经确认不可逆，之后即使传入更早时刻也仍被拒绝。尚无成功记录的编号按本次
// 参数处理：空编号、空承诺编号、非正数量返回 ErrInvalidParam，引用未知承诺返回
// ErrNotFound，这些提前失败不用本次时刻确认到期，也不占用编号，修正内容后仍可
// 提交。已全部使用的承诺不再接受新使用。
func (s *Store) Use(usageID, commitID string, quantity int, now time.Time) (Usage, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// 已成功的编号优先按重复提交处理，优先于本次参数校验：沿用成功编号但把
	// 承诺编号改成空串或未知承诺、把数量改成零或负数等本身非法的内容，仍属于
	// 对已成功提交内容的改动，按 ErrConflict 处理，与普通非法输入区分。成功
	// 使用的编号必非空，因此空编号不会命中这里，继续走参数校验。
	if existing, ok := s.usages[usageID]; ok {
		if existing.CommitmentID != commitID || existing.Quantity != quantity {
			return Usage{}, fmt.Errorf("%w: usage id %q reused with different content", ErrConflict, usageID)
		}
		return *existing, nil
	}

	if usageID == "" || commitID == "" {
		return Usage{}, fmt.Errorf("%w: usage/commit id must not be empty", ErrInvalidParam)
	}
	if quantity <= 0 {
		return Usage{}, fmt.Errorf("%w: usage quantity must be a positive integer", ErrInvalidParam)
	}

	c, ok := s.commitments[commitID]
	if !ok {
		return Usage{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
	}
	// 新使用判断：按本次时刻确认这一笔承诺是否到期。一经确认不可逆，之后
	// 即使传入更早时刻也一律关闭。已取消的承诺不确认到期，仍保持 canceled。
	s.confirmExpiryLocked(c, now)
	if c.Canceled {
		return Usage{}, fmt.Errorf("%w: commitment %q is canceled", ErrCommitmentClosed, commitID)
	}
	if c.Expired {
		return Usage{}, fmt.Errorf("%w: commitment %q expired at %v", ErrCommitmentClosed, commitID, c.Expiry)
	}
	if quantity > c.Quantity-c.Used {
		return Usage{}, fmt.Errorf("%w: need %d, unused %d", ErrUsageExceeded, quantity, c.Quantity-c.Used)
	}

	c.Used += quantity
	s.parts[c.PartID].Stock -= quantity
	u := &Usage{ID: usageID, CommitmentID: commitID, Quantity: quantity}
	s.usages[usageID] = u
	return *u, nil
}

// Cancel 取消承诺，只释放未用数量，不影响已扣减的实物库存。
// 重复取消不增加库存；承诺已到期时余量已自动失效，取消同样不产生变化。
// 取消后的承诺不能继续使用。
func (s *Store) Cancel(commitID string, now time.Time) (Commitment, error) {
	if commitID == "" {
		return Commitment{}, fmt.Errorf("%w: commit id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	c, ok := s.commitments[commitID]
	if !ok {
		return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
	}
	if !c.Canceled {
		c.Canceled = true
	}
	return *c, nil
}

