1	package warranty
2	
3	import (
4		"errors"
5		"sync"
6		"testing"
7		"time"
8	)
9	
10	// 本文件回归保障“取消承诺释放未用占用”这一既有功能，在另一个保修请求正为
11	// 同一种备件提交新预留时的并发正确性。业务主例：
12	//
13	//	备件 part1 初始库存十件；
14	//	cOld6：请求 rA 的承诺预留六件，已成功使用两件（已领取实物两件）；
15	//	cOther4：请求 rB 的承诺预留四件，尚未使用。
16	//	此时实物剩余八件、有效占用八件（cOld6 未用四件 + cOther4 四件）、
17	//	可承诺数量为零。
18	//
19	// 第三个具备保修资格的请求 rC 使用从未成功过的新承诺编号申请预留四件，这次
20	// 提交与取消 cOld6 同时发生，不预设谁先被处理。两种先后关系都合法：
21	//
22	//   - 新预留在取消生效前被处理：可承诺为零，返回 ErrInsufficientStock，不创建
23	//     新承诺、不留下任何占用；取消完成后实物八件、有效占用四件、可承诺四件。
24	//   - 取消先生效：cOld6 未用的四件被释放（已用两件不回补实物库存），新预留
25	//     成功，最终实物仍八件、有效占用八件、可承诺为零。
26	//
27	// 无论哪种结果，cOld6 最终都必须显示已取消并保留原定六件、已用两件、未用四件
28	// 及原到期时刻；cOther4 的状态、数量与归属不变；不能出现预留成功却没有对应
29	// 占用的结果。另覆盖取消释放后、四件尚未被新承诺占用时申请五件的边界。
30	// 这些测试只沿用登记、资格、预留、使用、取消与查询等既有公开入口、错误类别
31	// 及资格、到期和编号重试规则。
32	
33	const (
34		crPart     = "part1"
35		crReqOld   = "rA"
36		crReqOther = "rB"
37		crReqNew   = "rC"
38		crOld      = "cOld6"
39		crOther    = "cOther4"
40		crNew      = "cNew4"
41		crFive     = "cNew5"
42		crFour     = "cNew4b"
43		crUsage    = "uOldUsed2"
44	)
45	
46	var (
47		crExpiryOld   = t0.Add(40 * day)
48		crExpiryOther = t0.Add(30 * day)
49		crExpiryNew   = t0.Add(45 * day)
50		// crRaceNow 是取消与新预留并发提交的当前时刻，早于全部承诺到期时刻，
51		// 也在保修期内；查询沿用稍后但仍早于最早到期时刻的 crCheckNow。
52		crRaceNow  = nowOK.Add(time.Hour)
53		crCheckNow = crRaceNow.Add(time.Hour)
54	)
55	
56	// cancelReleaseStore 构造上述业务主例并断言取消前的初始账目：实物八件、
57	// 有效占用八件、可承诺为零。
58	func cancelReleaseStore(t *testing.T) *Store {
59		t.Helper()
60		s := NewStore()
61		if err := s.RegisterProduct("p1", t0, 30, nil); err != nil {
62			t.Fatalf("register product: %v", err)
63		}
64		if err := s.RegisterPart(crPart, 10); err != nil {
65			t.Fatalf("register part: %v", err)
66		}
67		for _, id := range []string{crReqOld, crReqOther, crReqNew} {
68			if err := s.SubmitRequest(id, "p1", "FAULTY"); err != nil {
69				t.Fatalf("submit request %s: %v", id, err)
70			}
71		}
72		if _, err := s.Reserve(crOld, crReqOld, crPart, 6, crExpiryOld, nowOK); err != nil {
73			t.Fatalf("reserve %s: %v", crOld, err)
74		}
75		if _, err := s.Reserve(crOther, crReqOther, crPart, 4, crExpiryOther, nowOK); err != nil {
76			t.Fatalf("reserve %s: %v", crOther, err)
77		}
78		if _, err := s.Use(crUsage, crOld, 2, nowOK); err != nil {
79			t.Fatalf("use 2 from %s: %v", crOld, err)
80		}
81		st, err := s.PartStatus(crPart, crCheckNow)
82		if err != nil {
83			t.Fatalf("part status baseline: %v", err)
84		}
85		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 8 || st.Committable != 0 {
86			t.Fatalf("baseline account: phys=%d occupied=%d committable=%d, want 8/8/0",
87				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
88		}
89		return s
90	}
91	
92	// crRaceResult 收集一次并发“取消 + 新预留”的两个返回值。
93	type crRaceResult struct {
94		canceled   Commitment
95		cancelErr  error
96		reserved   Commitment
97		reserveErr error
98	}
99	
100	// fanOutCancelReserve 让取消 cOld6 与新预留（新编号、四件）在同一道闸机释放后
101	// 同时进入仓库，尽量制造交叉；两者的实际先后不由测试预设。
102	func fanOutCancelReserve(t *testing.T, s *Store, newID string, now time.Time) crRaceResult {
103		t.Helper()
104		var rr crRaceResult
105		var wg sync.WaitGroup
106		start := make(chan struct{})
107	
108		wg.Add(1)
109		go func() {
110			defer wg.Done()
111			<-start
112			rr.canceled, rr.cancelErr = s.Cancel(crOld, now)
113		}()
114		wg.Add(1)
115		go func() {
116			defer wg.Done()
117			<-start
118			rr.reserved, rr.reserveErr = s.Reserve(newID, crReqNew, crPart, 4, crExpiryNew, now)
119		}()
120		close(start)
121		wg.Wait()
122		return rr
123	}
124	
125	// assertCancelReleaseFixedCommitments 核对与本次并发结果无关的既有事实：
126	// cOld6 已取消但保留原定六件、已用两件、未用四件、归属与原到期时刻，其成功
127	// 使用记录仍在（已领取实物不回库存）；cOther4 完全不受影响。
128	func assertCancelReleaseFixedCommitments(t *testing.T, s *Store) {
129		t.Helper()
130		old, err := s.Commitment(crOld)
131		if err != nil {
132			t.Fatalf("commitment %s: %v", crOld, err)
133		}
134		if !old.Canceled || old.Expired || old.Quantity != 6 || old.Used != 2 ||
135			old.Unused() != 4 || old.RequestID != crReqOld || old.PartID != crPart ||
136			!old.Expiry.Equal(crExpiryOld) {
137			t.Fatalf("old commitment after cancel: %+v, want canceled qty=6 used=2 unused=4", old)
138		}
139		// 已成功领取的两件实物保留为使用记录，取消不抹除它们。
140		usages, err := s.CommitmentUsages(crOld)
141		if err != nil {
142			t.Fatalf("usages of %s: %v", crOld, err)
143		}
144		if len(usages) != 1 || usages[0] != (Usage{ID: crUsage, CommitmentID: crOld, Quantity: 2}) {
145			t.Fatalf("usages of old commitment = %+v, want single 2-piece usage", usages)
146		}
147		other, err := s.Commitment(crOther)
148		if err != nil {
149			t.Fatalf("commitment %s: %v", crOther, err)
150		}
151		if other.Canceled || other.Expired || other.Quantity != 4 || other.Used != 0 ||
152			other.Unused() != 4 || other.RequestID != crReqOther || other.PartID != crPart ||
153			!other.Expiry.Equal(crExpiryOther) {
154			t.Fatalf("other commitment disturbed: %+v, want active qty=4 used=0", other)
155		}
156	}
157	
158	// assertCancelReleaseNewRequestHistory 核对 rC 的预留处理历史与实际结果一致：
159	// 只有一条记录，成功或库存不足失败（含处理前库存依据快照）二选一，资格依据
160	// 均为合格。
161	func assertCancelReleaseNewRequestHistory(t *testing.T, s *Store, succeeded bool, wantBasis StockBasis) {
162		t.Helper()
163		hist, err := s.RequestHistory(crReqNew)
164		if err != nil {
165			t.Fatalf("request history %s: %v", crReqNew, err)
166		}
167		if len(hist) != 1 {
168			t.Fatalf("rC history len = %d, want exactly 1 record", len(hist))
169		}
170		rec := hist[0]
171		if rec.Seq != 1 || rec.CommitID != crNew || rec.PartID != crPart ||
172			rec.Quantity != 4 || !rec.Expiry.Equal(crExpiryNew) || !rec.Now.Equal(crRaceNow) {
173			t.Fatalf("rC record submission fields = %+v", rec)
174		}
175		if rec.Eligibility == nil || !rec.Eligibility.Eligible || rec.Eligibility.Excluded ||
176			rec.Eligibility.RequestID != crReqNew || len(rec.Eligibility.Reasons) != 0 {
177			t.Fatalf("rC record eligibility = %+v, want eligible snapshot", rec.Eligibility)
178		}
179		if rec.StockBasis == nil ||
180			rec.StockBasis.PhysicalRemaining != wantBasis.PhysicalRemaining ||
181			rec.StockBasis.ActiveOccupied != wantBasis.ActiveOccupied ||
182			rec.StockBasis.Committable != wantBasis.Committable {
183			t.Fatalf("rC record stock basis = %+v, want %+v", rec.StockBasis, wantBasis)
184		}
185		if succeeded {
186			if !rec.Success || rec.Error != "" {
187				t.Fatalf("rC record = %+v, want success", rec)
188			}
189		} else {
190			if rec.Success || rec.Error != HistoryErrorInsufficientStock {
191				t.Fatalf("rC record = %+v, want insufficient_stock failure", rec)
192			}
193		}
194	}
195	
196	// assertCancelReleaseOutcome 在并发结束后核对全部不变量。succeeded 仅用于交叉
197	// 校验调用方对 rr.reserveErr 的分支判断；账目、明细、查询与历史的期望值全部
198	// 按仓库实际状态从该分支推导，不预设固定结果。
199	func assertCancelReleaseOutcome(t *testing.T, s *Store, rr crRaceResult, succeeded bool, now time.Time) {
200		t.Helper()
201	
202		// 取消无论先后都成功，返回值即显示已取消并保留全部原定/已用/未用事实。
203		if rr.cancelErr != nil {
204			t.Fatalf("concurrent cancel: %v", rr.cancelErr)
205		}
206		if !rr.canceled.Canceled || rr.canceled.Quantity != 6 || rr.canceled.Used != 2 ||
207			rr.canceled.Unused() != 4 || rr.canceled.RequestID != crReqOld ||
208			!rr.canceled.Expiry.Equal(crExpiryOld) {
209			t.Fatalf("cancel result = %+v, want canceled 6/used2/unused4", rr.canceled)
210		}
211	
212		st, err := s.PartStatus(crPart, now)
213		if err != nil {
214			t.Fatalf("part status after race: %v", err)
215		}
216		// 实物剩余始终为八：预留不扣实物，取消不回补已领取的两件。
217		if st.PhysicalRemaining != 8 {
218			t.Fatalf("physical remaining = %d, want 8", st.PhysicalRemaining)
219		}
220	
221		wantNew := Commitment{
222			ID:        crNew,
223			RequestID: crReqNew,
224			PartID:    crPart,
225			Quantity:  4,
226			Expiry:    crExpiryNew,
227		}
228	
229		switch {
230		case succeeded:
231			// 取消先生效：新预留成功并返回完整的首次承诺（已用为零、未取消）。
232			if rr.reserveErr != nil {
233				t.Fatalf("reserve after cancel released stock: %v", rr.reserveErr)
234			}
235			if rr.reserved != wantNew || rr.reserved.Used != 0 ||
236				rr.reserved.Canceled || rr.reserved.Expired {
237				t.Fatalf("new reserve result = %+v, want %+v", rr.reserved, wantNew)
238			}
239			// 实物八件、有效占用八件（cOther4 + cNew4）、可承诺为零。
240			if st.ActiveOccupied != 8 || st.Committable != 0 {
241				t.Fatalf("account on success branch: occupied=%d committable=%d, want 8/0",
242					st.ActiveOccupied, st.Committable)
243			}
244			if len(st.Details) != 3 {
245				t.Fatalf("part details len = %d, want 3 (old canceled + other + new)", len(st.Details))
246			}
247			dNew := mustDetailByID(t, st.Details, crNew)
248			if dNew.Status != CommitmentActive || dNew.RequestID != crReqNew ||
249				dNew.PartID != crPart || dNew.OriginalQuantity != 4 ||
250				dNew.UsedQuantity != 0 || dNew.RemainingQuantity != 4 ||
251				!dNew.Expiry.Equal(crExpiryNew) {
252				t.Fatalf("new detail = %+v, want active 4/0/4 for rC", dNew)
253			}
254			got, err := s.Commitment(crNew)
255			if err != nil || got != wantNew {
256				t.Fatalf("stored new commitment = %+v, err %v; want %+v", got, err, wantNew)
257			}
258			view, err := s.RequestView(crReqNew, now)
259			if err != nil {
260				t.Fatalf("request view rC: %v", err)
261			}
262			if view.Eligibility == nil || !view.Eligibility.Eligible || len(view.Commitments) != 1 ||
263				view.Commitments[0].CommitmentID != crNew || view.Commitments[0].Status != CommitmentActive {
264				t.Fatalf("rC view = elig %+v commitments %+v, want single active %s",
265					view.Eligibility, view.Commitments, crNew)
266			}
267			// 成功时处理前账目是取消后的 8/4/4。
268			assertCancelReleaseNewRequestHistory(t, s, true, StockBasis{8, 4, 4})
269	
270		case errors.Is(rr.reserveErr, ErrInsufficientStock):
271			// 新预留在取消生效前被处理：ErrInsufficientStock，返回空承诺，不创建记录。
272			if rr.reserved != (Commitment{}) {
273				t.Fatalf("failed reserve returned commitment = %+v, want empty", rr.reserved)
274			}
275			// 取消随后完成：实物八件、有效占用四件（只剩 cOther4）、可承诺四件。
276			if st.ActiveOccupied != 4 || st.Committable != 4 {
277				t.Fatalf("account on failure branch: occupied=%d committable=%d, want 4/4",
278					st.ActiveOccupied, st.Committable)
279			}
280			if len(st.Details) != 2 {
281				t.Fatalf("part details len = %d, want 2 (no failed new commitment)", len(st.Details))
282			}
283			if _, err := s.Commitment(crNew); !errors.Is(err, ErrNotFound) {
284				t.Fatalf("failed commitment lookup: got %v / err %v, want ErrNotFound", rr.reserved, err)
285			}
286			view, err := s.RequestView(crReqNew, now)
287			if err != nil {
288				t.Fatalf("request view rC: %v", err)
289			}
290			if view.Eligibility == nil || !view.Eligibility.Eligible || len(view.Commitments) != 0 {
291				t.Fatalf("rC view = elig %+v commitments %+v, want eligible with no commitments",
292					view.Eligibility, view.Commitments)
293			}
294			// 失败时处理前账目是取消前的 8/8/0。
295			assertCancelReleaseNewRequestHistory(t, s, false, StockBasis{8, 8, 0})
296	
297		default:
298			t.Fatalf("concurrent reserve returned unexpected error: %v (commitment %+v)",
299				rr.reserveErr, rr.reserved)
300		}
301	
302		// 备件明细中已取消的 cOld6 必须保留可追查，cOther4 保持有效；活动明细的
303		// 未用数量之和必须恰好等于有效占用，杜绝“预留成功却没有对应占用”。
304		dOld := mustDetailByID(t, st.Details, crOld)
305		if dOld.Status != CommitmentCanceled || dOld.RequestID != crReqOld ||
306			dOld.OriginalQuantity != 6 || dOld.UsedQuantity != 2 || dOld.RemainingQuantity != 4 ||
307			!dOld.Expiry.Equal(crExpiryOld) {
308			t.Fatalf("old detail = %+v, want canceled 6/2/4", dOld)
309		}
310		dOther := mustDetailByID(t, st.Details, crOther)
311		if dOther.Status != CommitmentActive || dOther.RequestID != crReqOther ||
312			dOther.OriginalQuantity != 4 || dOther.UsedQuantity != 0 || dOther.RemainingQuantity != 4 ||
313			!dOther.Expiry.Equal(crExpiryOther) {
314			t.Fatalf("other detail = %+v, want active 4/0/4", dOther)
315		}
316		activeUnused := 0
317		for _, d := range st.Details {
318			if d.Status == CommitmentActive {
319				activeUnused += d.RemainingQuantity
320			}
321		}
322		if activeUnused != st.ActiveOccupied {
323			t.Fatalf("active details unused sum = %d, want ActiveOccupied %d", activeUnused, st.ActiveOccupied)
324		}
325		if st.PhysicalRemaining-st.ActiveOccupied != st.Committable {
326			t.Fatalf("committable %d != physical %d - occupied %d",
327				st.Committable, st.PhysicalRemaining, st.ActiveOccupied)
328		}
329	
330		// 按请求查看：rA 仍只看到已取消的旧记录，rB 仍只看到自己未受影响的承诺。
331		viewA, err := s.RequestView(crReqOld, now)
332		if err != nil {
333			t.Fatalf("request view rA: %v", err)
334		}
335		if len(viewA.Commitments) != 1 {
336			t.Fatalf("rA commitments = %d, want 1 (canceled record retained)", len(viewA.Commitments))
337		}
338		if d := viewA.Commitments[0]; d.CommitmentID != crOld || d.Status != CommitmentCanceled ||
339			d.OriginalQuantity != 6 || d.UsedQuantity != 2 || d.RemainingQuantity != 4 ||
340			!d.Expiry.Equal(crExpiryOld) {
341			t.Fatalf("rA view of old commitment = %+v", d)
342		}
343		viewB, err := s.RequestView(crReqOther, now)
344		if err != nil {
345			t.Fatalf("request view rB: %v", err)
346		}
347		if len(viewB.Commitments) != 1 {
348			t.Fatalf("rB commitments = %d, want 1", len(viewB.Commitments))
349		}
350		if d := viewB.Commitments[0]; d.CommitmentID != crOther || d.Status != CommitmentActive ||
351			d.OriginalQuantity != 4 || d.UsedQuantity != 0 || d.RemainingQuantity != 4 ||
352			!d.Expiry.Equal(crExpiryOther) {
353			t.Fatalf("rB view changed after cancel/reserve race: %+v", d)
354		}
355	
356		// 取消与新预留都不向两个既有请求追加历史：各自只有建仓时的一条成功记录。
357		for _, rid := range []string{crReqOld, crReqOther} {
358			hist, err := s.RequestHistory(rid)
359			if err != nil {
360				t.Fatalf("history %s: %v", rid, err)
361			}
362			if len(hist) != 1 || !hist[0].Success {
363				t.Fatalf("history of %s = %+v, want single original success record", rid, hist)
364			}
365		}
366	
367		assertCancelReleaseFixedCommitments(t, s)
368	}
369	
370	// TestConcurrentCancelAndNewReserveEitherOrderValid 主并发回归：取消旧承诺与
371	// rC 的四件新预留同时发生，不预设处理先后。每次迭代允许出现任一合法结果
372	// （成功并占满释放量，或 ErrInsufficientStock 且取消后释放四件），但两种先后
373	// 关系下的全部账目、明细、查询与历史不变量都必须成立，不能出现成功却无占用
374	// 或失败却留下承诺等中间态。
375	func TestConcurrentCancelAndNewReserveEitherOrderValid(t *testing.T) {
376		const iterations = 50
377		var sawSuccess, sawFailure int
378		for i := 0; i < iterations; i++ {
379			t.Run("iteration", func(t *testing.T) {
380				s := cancelReleaseStore(t)
381				rr := fanOutCancelReserve(t, s, crNew, crRaceNow)
382				switch {
383				case rr.reserveErr == nil:
384					sawSuccess++
385				case errors.Is(rr.reserveErr, ErrInsufficientStock):
386					sawFailure++
387				default:
388					t.Fatalf("iteration: unexpected reserve error %v", rr.reserveErr)
389				}
390				assertCancelReleaseOutcome(t, s, rr, rr.reserveErr == nil, crCheckNow)
391			})
392		}
393		// 仅作信息记录：两种先后关系在足量迭代下通常都会真实发生；即使某次运行
394		// 调度只给出一侧，assertCancelReleaseOutcome 也已覆盖该侧的全部不变量。
395		t.Logf("across %d iterations: reserve-after-cancel successes=%d, reserve-before-cancel failures=%d",
396			iterations, sawSuccess, sawFailure)
397	}
398	
399	// TestReserveBeforeCancelFailsThenCancelReleasesFour 确定地覆盖“新预留先被
400	// 处理”的先后关系：可承诺为零时四件预留返回 ErrInsufficientStock 且不创建
401	// 承诺；随后取消完成，只释放旧承诺未用的四件，实物仍八件。失败不占用编号，
402	// 取消生效后用同一编号以相同内容再次提交应当成功（这是失败后的新提交，不是
403	// 幂等重试），最终账目与“取消先成功”一侧一致。
404	func TestReserveBeforeCancelFailsThenCancelReleasesFour(t *testing.T) {
405		s := cancelReleaseStore(t)
406	
407		// 取消尚未生效：可承诺为零，整次拒绝。
408		c, err := s.Reserve(crNew, crReqNew, crPart, 4, crExpiryNew, crRaceNow)
409		if !errors.Is(err, ErrInsufficientStock) || c != (Commitment{}) {
410			t.Fatalf("reserve before cancel: c=%+v err=%v, want ErrInsufficientStock", c, err)
411		}
412		if _, err := s.Commitment(crNew); !errors.Is(err, ErrNotFound) {
413			t.Fatalf("failed reserve created commitment: err=%v", err)
414		}
415		// 失败不改变账目：实物八件、占用八件、可承诺零。
416		if st, _ := s.PartStatus(crPart, crCheckNow); st.PhysicalRemaining != 8 ||
417			st.ActiveOccupied != 8 || st.Committable != 0 {
418			t.Fatalf("state after failed reserve: %+v, want 8/8/0", st)
419		}
420	
421		// 随后取消：释放未用四件，已用两件不回补实物。
422		canceled, err := s.Cancel(crOld, crRaceNow.Add(time.Minute))
423		if err != nil {
424			t.Fatalf("cancel after failed reserve: %v", err)
425		}
426		if !canceled.Canceled || canceled.Quantity != 6 || canceled.Used != 2 || canceled.Unused() != 4 {
427			t.Fatalf("cancel result = %+v", canceled)
428		}
429		st, _ := s.PartStatus(crPart, crCheckNow)
430		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 4 || st.Committable != 4 {
431			t.Fatalf("state after cancel: phys=%d occupied=%d committable=%d, want 8/4/4",
432				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
433		}
434	
435		// 失败记录不占用新编号：取消生效后用相同内容再次提交应当首次成功。
436		later := crCheckNow.Add(time.Hour)
437		got, err := s.Reserve(crNew, crReqNew, crPart, 4, crExpiryNew, later)
438		if err != nil {
439			t.Fatalf("resubmit same id after cancel: %v", err)
440		}
441		wantNew := Commitment{ID: crNew, RequestID: crReqNew, PartID: crPart, Quantity: 4, Expiry: crExpiryNew}
442		if got != wantNew {
443			t.Fatalf("resubmitted commitment = %+v, want %+v", got, wantNew)
444		}
445		st2, _ := s.PartStatus(crPart, later)
446		if st2.PhysicalRemaining != 8 || st2.ActiveOccupied != 8 || st2.Committable != 0 {
447			t.Fatalf("state after resubmit: %+v, want phys=8 occupied=8 committable=0", st2)
448		}
449	
450		// rC 历史两条：先是取消前库存不足失败（依据 8/8/0），再是取消后成功
451		// （依据 8/4/4），序号连续，失败记录不是承诺、成功记录必有对应占用。
452		hist, err := s.RequestHistory(crReqNew)
453		if err != nil {
454			t.Fatalf("rC history: %v", err)
455		}
456		if len(hist) != 2 {
457			t.Fatalf("rC history len = %d, want 2", len(hist))
458		}
459		if hist[0].Seq != 1 || hist[0].Success || hist[0].Error != HistoryErrorInsufficientStock ||
460			hist[0].StockBasis == nil || hist[0].StockBasis.Committable != 0 {
461			t.Fatalf("rC failure record = %+v", hist[0])
462		}
463		if hist[1].Seq != 2 || !hist[1].Success || hist[1].Error != "" ||
464			hist[1].StockBasis == nil || hist[1].StockBasis.ActiveOccupied != 4 ||
465			hist[1].StockBasis.Committable != 4 {
466			t.Fatalf("rC success record = %+v", hist[1])
467		}
468	
469		assertCancelReleaseFixedCommitments(t, s)
470	}
471	
472	// TestCancelBeforeReserveSucceedsAndRetryRulesHold 确定地覆盖“取消先生效”的
473	// 先后关系：旧承诺未用四件释放后，rC 的四件预留成功，实物仍八件、可承诺归零。
474	// 新承诺随后沿用既有编号重试规则：相同内容原样取回首次承诺，不重复占用、不
475	// 追加历史；改数量即 ErrConflict，库存与归属不变。
476	func TestCancelBeforeReserveSucceedsAndRetryRulesHold(t *testing.T) {
477		s := cancelReleaseStore(t)
478	
479		if _, err := s.Cancel(crOld, crRaceNow); err != nil {
480			t.Fatalf("cancel before reserve: %v", err)
481		}
482		st, _ := s.PartStatus(crPart, crCheckNow)
483		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 4 || st.Committable != 4 {
484			t.Fatalf("state after cancel only: %+v, want 8/4/4", st)
485		}
486	
487		got, err := s.Reserve(crNew, crReqNew, crPart, 4, crExpiryNew, crRaceNow.Add(time.Minute))
488		if err != nil {
489			t.Fatalf("reserve freed four: %v", err)
490		}
491		wantNew := Commitment{ID: crNew, RequestID: crReqNew, PartID: crPart, Quantity: 4, Expiry: crExpiryNew}
492		if got != wantNew {
493			t.Fatalf("new commitment = %+v, want %+v", got, wantNew)
494		}
495	
496		// 原样重试（当前时刻不同也不影响）：取回首次承诺，不重复占用、不追加历史。
497		retryNow := crCheckNow.Add(time.Hour)
498		again, err := s.Reserve(crNew, crReqNew, crPart, 4, crExpiryNew, retryNow)
499		if err != nil || again != wantNew {
500			t.Fatalf("idempotent retry = %+v err %v, want %+v", again, err, wantNew)
501		}
502		st2, _ := s.PartStatus(crPart, retryNow)
503		if st2.PhysicalRemaining != 8 || st2.ActiveOccupied != 8 || st2.Committable != 0 {
504			t.Fatalf("idempotent retry changed stock: %+v", st2)
505		}
506		hist, _ := s.RequestHistory(crReqNew)
507		if len(hist) != 1 || !hist[0].Success {
508			t.Fatalf("rC history after retry = %+v, want single success record", hist)
509		}
510	
511		// 改数量复用编号：ErrConflict，不改变库存与归属，冲突失败记录挂在 rC 下。
512		if conflict, err := s.Reserve(crNew, crReqNew, crPart, 5, crExpiryNew, retryNow); !errors.Is(err, ErrConflict) {
513			t.Fatalf("retry with changed quantity: c=%+v err=%v, want ErrConflict", conflict, err)
514		}
515		st3, _ := s.PartStatus(crPart, retryNow)
516		if st3.PhysicalRemaining != 8 || st3.ActiveOccupied != 8 || st3.Committable != 0 {
517			t.Fatalf("conflict retry changed stock: %+v", st3)
518		}
519		stored, err := s.Commitment(crNew)
520		if err != nil || stored != wantNew {
521			t.Fatalf("new commitment overwritten by conflict attempt: %+v err %v", stored, err)
522		}
523		hist2, _ := s.RequestHistory(crReqNew)
524		if len(hist2) != 2 || hist2[1].Success || hist2[1].Error != HistoryErrorConflict ||
525			hist2[1].Eligibility != nil || hist2[1].StockBasis != nil {
526			t.Fatalf("rC history after conflict = %+v, want appended conflict record with nil basis", hist2)
527		}
528	
529		assertCancelReleaseFixedCommitments(t, s)
530	}
531	
532	// TestAfterCancelFreedFourReserveFiveRejectedWhole 边界回归：取消释放后四件
533	// 尚未被新承诺占用（实物八件、有效占用四件、可承诺四件），第三张请求申请五件
534	// 必须整次拒绝：返回 ErrInsufficientStock，不创建承诺，实物库存与其他承诺的
535	// 占用均不改变。失败不消耗可承诺数量，随后申请恰好四件应成功。
536	func TestAfterCancelFreedFourReserveFiveRejectedWhole(t *testing.T) {
537		s := cancelReleaseStore(t)
538	
539		if _, err := s.Cancel(crOld, crRaceNow); err != nil {
540			t.Fatalf("cancel: %v", err)
541		}
542		st, _ := s.PartStatus(crPart, crCheckNow)
543		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 4 || st.Committable != 4 {
544			t.Fatalf("state after cancel: %+v, want 8/4/4", st)
545		}
546	
547		// 可承诺只有四件：申请五件整次拒绝。
548		c, err := s.Reserve(crFive, crReqNew, crPart, 5, crExpiryNew, crCheckNow)
549		if !errors.Is(err, ErrInsufficientStock) || c != (Commitment{}) {
550			t.Fatalf("reserve five against four committable: c=%+v err=%v, want ErrInsufficientStock", c, err)
551		}
552		if _, err := s.Commitment(crFive); !errors.Is(err, ErrNotFound) {
553			t.Fatalf("rejected five-piece reserve left a commitment: err=%v", err)
554		}
555	
556		// 实物库存、有效占用、可承诺数量与其他承诺均不改变。
557		st2, err := s.PartStatus(crPart, crCheckNow)
558		if err != nil {
559			t.Fatalf("part status after rejection: %v", err)
560		}
561		if st2.PhysicalRemaining != 8 || st2.ActiveOccupied != 4 || st2.Committable != 4 {
562			t.Fatalf("rejected reserve changed stock: %+v, want 8/4/4", st2)
563		}
564		if len(st2.Details) != 2 {
565			t.Fatalf("details len = %d, want 2 (old canceled + other)", len(st2.Details))
566		}
567		assertCancelReleaseFixedCommitments(t, s)
568	
569		// 失败记录与实际预留一致：一条库存不足记录，处理前依据为 8/4/4。
570		hist, err := s.RequestHistory(crReqNew)
571		if err != nil {
572			t.Fatalf("rC history: %v", err)
573		}
574		if len(hist) != 1 || hist[0].Success || hist[0].Error != HistoryErrorInsufficientStock ||
575			hist[0].CommitID != crFive || hist[0].Quantity != 5 ||
576			hist[0].StockBasis == nil || hist[0].StockBasis.PhysicalRemaining != 8 ||
577			hist[0].StockBasis.ActiveOccupied != 4 || hist[0].StockBasis.Committable != 4 {
578			t.Fatalf("rC rejection record = %+v", hist)
579		}
580	
581		// 被整次拒绝没有消耗任何可承诺数量：另一个新编号申请恰好四件应当成功，
582		// 成功后实物仍八件、有效占用八件、可承诺为零。
583		later := crCheckNow.Add(time.Hour)
584		four, err := s.Reserve(crFour, crReqNew, crPart, 4, crExpiryNew, later)
585		if err != nil {
586			t.Fatalf("reserve exact four after five rejected: %v", err)
587		}
588		if four.Quantity != 4 || four.RequestID != crReqNew || four.Used != 0 ||
589			four.Canceled || four.Expired {
590			t.Fatalf("exact-four commitment = %+v", four)
591		}
592		st3, _ := s.PartStatus(crPart, later)
593		if st3.PhysicalRemaining != 8 || st3.ActiveOccupied != 8 || st3.Committable != 0 {
594			t.Fatalf("stock after exact-four reserve: %+v, want 8/8/0", st3)
595		}
596	}
